// The one content-based exclusion left: a lockfile by exact name AND whole
// content (decision D5-2, contract C6).
func TestLockfilesAreRecognisedByNameAndWholeContent(t *testing.T) {
	root := t.TempDir()
	for name, body := range lockfileSamples {
		if v := classify(t, root, "sub/"+name, body); v.Reason != ReasonLockfile {
			t.Errorf("%s: %q, want a lockfile", name, v.Reason)
		}
	}
	// Yarn Berry is its own format under the same name.
	if v := classify(t, root, "berry/yarn.lock", yarnBerry); v.Reason != ReasonLockfile {
		t.Errorf("yarn berry lock: %q", v.Reason)
	}
}

func TestEveryListedLockfileNameHasASample(t *testing.T) {
	for name := range lockfiles {
		if _, ok := lockfileSamples[name]; !ok {
			t.Errorf("%s is on the lockfile list with no sample in this test", name)
		}
	}
	if len(lockfiles) != len(lockfileSamples) {
		t.Errorf("%d lockfile names, %d samples", len(lockfiles), len(lockfileSamples))
	}
}

// A name is not evidence, and neither is a head that parses: the whole content
// must be the format (round-5 review items 1 and 7 for lockfiles).
func TestALockfileNameHoldingAnythingElseIsInScope(t *testing.T) {
	root := t.TempDir()
	source := "import os, subprocess\nsubprocess.call('ls ' + os.environ['D'], shell=True)\nAWS_KEY = 'AKIAIOSFODNN7EXAMPLE'\n"
	secret := `AWS_SECRET_ACCESS_KEY = "wJalrXUtnFEMI/K7MDENG/bPxRfiCYEXAMPLEKEY"` + "\n"
	cases := map[string]string{
		// Not the format at all.
		"package-lock.json": `{"name": "not a lockfile"}`,
		"yarn.lock":         "just some notes\n",
		"go.sum":            "this is not a go.sum\n",
		"Gemfile.lock":      source,
		"poetry.lock":       source,
		"Cargo.lock":        source,
		"pnpm-lock.yaml":    source,
		"composer.lock":     `{"content-hash":"x","packages":[]} ` + source,
		"Pipfile.lock":      "{}",
	}
	for name, body := range cases {
		if v := classify(t, root, "n/"+name, body); !v.None() {
			t.Errorf("%s with arbitrary content: %q, want in scope", name, v.Reason)
		}
	}
	// A valid first part and anything after it: the whole file is read.
	trailing := map[string]string{
		"package-lock.json": strings.TrimSuffix(npmLockV3, "}") + `, "x": "AKIAIOSFODNN7EXAMPLE"}`,
		"yarn.lock":         yarnV1 + "\n" + source,
		"go.sum":            goSum + secret,
		"Gemfile.lock":      gemLock + source,
		"poetry.lock":       poetryLock + source,
		"Cargo.lock":        cargoLock + "exec('ls ' + x)\n",
		"pnpm-lock.yaml":    pnpmLock + source,
		"composer.lock":     composerLock + "\n<?php system($_GET['c']); ?>",
		"Pipfile.lock":      pipfileLock + source,
	}
	for name, body := range trailing {
		if v := classify(t, root, "t/"+name, body); !v.None() {
			t.Errorf("%s: a valid head and trailing content was %q; the whole file must be the format", name, v.Reason)
		}
	}
	// A valid lockfile with one unknown key (where a secret could be hidden).
	if v := classify(t, root, "k/package-lock.json", strings.Replace(npmLockV3, `"requires": true,`, `"requires": true, "note": "AKIAIOSFODNN7EXAMPLE",`, 1)); !v.None() {
		t.Errorf("an unknown key in a package-lock.json: %q", v.Reason)
	}
	if v := classify(t, root, "k2/yarn.lock", strings.Replace(yarnV1, `  version "4.17.21"`, `  version "4.17.21"`+"\n  token \"x\"; exec(y)", 1)); !v.None() {
		t.Errorf("an unknown field in a yarn.lock: %q", v.Reason)
	}
}

// Decision D5-2: nothing but a lockfile is excluded for what it looks like.
func TestNoContentHeuristicExcludesAFile(t *testing.T) {
	root := t.TempDir()
	handler := "const Router = require('@koa/router');\nrouter.get('/u', async (ctx) => { await pool.query(\"SELECT * FROM u WHERE id = '\" + ctx.query.id + \"'\"); });\n"
	pad := strings.Repeat("function pad(a, b) { return a + b; }\n", 300)
	bigLiteral := "const COUNTRIES = [" + strings.Repeat(`{"code":"C","name":"N","region":{"id":0,"label":"R"},"vat":3},`, 700) + "];\n"
	minified := "!function(){" + strings.Repeat("a=b(c,d);", 400) + "}();\n"
	for _, tc := range []struct{ rel, body, what string }{
		{"jquery.js", "/*! jQuery v3.7.1 | (c) OpenJS Foundation */\n// jquery jquery jquery\n" + handler + pad, "a forged jQuery banner"},
		{"socketio.js", "/*! Socket.IO v4.7.2 | (c) 2014 */\n// socket socket socket\n" + handler + pad, "a forged Socket.IO banner"},
		{"lodash.js", "/** @license Lodash <https://lodash.com/> */\n// lodash lodash lodash\n" + handler + pad, "a forged Lodash banner"},
		{"react.js", "/** React v18.2.0 | MIT */\n// react react react\n" + handler + pad, "a forged React banner"},
		{"gen.go", "// Code generated by acme-gen v1.0. DO NOT EDIT.\npackage x\n", "a generator header"},
		{"gen.py", "# @generated\nimport os\n", "an @generated header"},
		{"api.pb.go", "// Generated by the protocol buffer compiler.  DO NOT EDIT!\npackage x\n", "a protobuf header"},
		{"routes.js", "const express = require('express');\n" + handler + bigLiteral, "first-party code with one large JSON literal"},
		{"routes.ts", handler + bigLiteral, "TypeScript with one large JSON literal"},
		{"bundle.js", minified, "minified-looking code"},
		{"app.min.js", minified, "a file called *.min.js"},
		{"site.min.css", "a{" + strings.Repeat("color:red;", 200) + "}\n", "a minified stylesheet"},
		{"dist/main.js", "/******/ (() => { // webpackBootstrap\n" + handler + "\n//# sourceMappingURL=main.js.map\n", "compiled output"},
		{"app.js.map", `{"version":3,"file":"app.js","sources":["a.ts"],"mappings":"AAAA"}`, "a source map"},
		{"vendor/lib/routes.js", handler, "code under vendor/"},
		{"node_modules/x/index.js", handler, "code under node_modules/"},
	} {
		if v := classify(t, root, tc.rel, tc.body); !v.None() {
			t.Errorf("%s: classified %q; every in-scope file under the cap is analysed", tc.what, v.Reason)
		}
	}
}

func TestClassifyFileOpensOnlyLockfileNames(t *testing.T) {
	root := t.TempDir()
	// A FIFO named like source is never opened: no verdict, and no blocking.
	// (A lockfile-named FIFO is below.)
	p := write(t, root, "a.js", "x")
	if v := ClassifyFile(p, "a.js", 1); !v.None() {
		t.Errorf("%q", v.Reason)
	}
	if v := ClassifyFile(filepath.Join(root, "missing", "package-lock.json"), "package-lock.json", 10); !v.None() {
		t.Errorf("a missing lockfile: %q", v.Reason)
	}
	if v := ClassifyFile(write(t, root, "empty/go.sum", ""), "go.sum", 0); !v.None() {
		t.Errorf("an empty lockfile: %q", v.Reason)
	}
}

// Marker and file probing never blocks and never follows a link (review item
// 9): a FIFO or a symbolic link with a lockfile's name is not a lockfile.
func TestAFifoOrLinkNamedLikeALockfileIsNeverRead(t *testing.T) {
	root := t.TempDir()
	fifo := filepath.Join(root, "package-lock.json")
	if err := mkfifo(fifo); err != nil {
		t.Skipf("no FIFOs here: %v", err)
	}
	done := make(chan Verdict, 1)
	go func() { done <- ClassifyFile(fifo, "package-lock.json", 100) }()
	select {
	case v := <-done:
		if !v.None() {
			t.Errorf("a FIFO named package-lock.json: %q", v.Reason)
		}
	case <-time.After(5 * time.Second):
		t.Fatal("ClassifyFile blocked on a FIFO")
	}
	// A link to a real lockfile outside the file's own place is not followed.
	real := write(t, root, "real/go.sum", goSum)
	link := filepath.Join(root, "link", "go.sum")
	if err := os.MkdirAll(filepath.Dir(link), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.Symlink(real, link); err != nil {
		t.Skipf("no symlinks here: %v", err)
	}
	if v := ClassifyFile(link, "link/go.sum", int64(len(goSum))); !v.None() {
		t.Errorf("a symlink named go.sum was read through: %q", v.Reason)
	}
	if v := ClassifyFile(real, "real/go.sum", int64(len(goSum))); v.Reason != ReasonLockfile {
		t.Errorf("the real file: %q", v.Reason)
	}
}

func TestALockfileOverTheParseBoundIsInScope(t *testing.T) {
	root := t.TempDir()
	p := write(t, root, "go.sum", goSum)
	if v := ClassifyFile(p, "go.sum", maxLockfileBytes+1); !v.None() {
		t.Errorf("a lockfile larger than the bound: %q", v.Reason)
	}
}
